// ELEMENTS:
// 1. Navy com o filete vermelho no topo
// 2. Frase (anim.text, **palavras** em Heavy)
// 3. Fluxo em três nós (nodes: "icon: legenda", icon = financas | selo | casa): círculos azul royal,
//    vermelho e branco que saltam em sequência, ligados por setas tracejadas em movimento
// 4. Pílula em contorno (tag) no fim; grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const BLUE = "#013BA9";
const RED = "#DE212B";
const WHITE = "#FFFFFF";
const MIST = "#C9D3E3";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const BACK = Easing.out(Easing.back(1.8));
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const ICONS: Record<string, string> = {
  financas: "M12 40 L50 20 L88 40 Z M18 46 H82 M24 46 V76 M40 46 V76 M60 46 V76 M76 46 V76 M14 82 H86",
  selo: "M28 50 L44 66 L74 34",
  casa: "M14 50 L50 20 L86 50 M24 44 V82 H76 V44 M42 82 V62 H58 V82",
};
const NODE = [
  { bg: BLUE, fg: WHITE },
  { bg: RED, fg: WHITE },
  { bg: WHITE, fg: NAVY },
];

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.28) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.07, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const FluxoAutomatico: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const tag = String(p.tag ?? "").trim();
  const nodes = (Array.isArray(p.nodes) ? (p.nodes as unknown[]).map(String) : []).slice(0, 3).map((s) => {
    const i = s.indexOf(":");
    return { icon: ICONS[(i > 0 ? s.slice(0, i) : s).trim()] ?? ICONS.selo, label: i > 0 ? s.slice(i + 1).trim() : "" };
  });
  const parts = String(anim.text ?? "").split(/(\*\*[^*]+\*\*)/).filter(Boolean);

  const show = (delay: number, len = 0.6, easing = EASE): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing });
  const D = 230 * u;
  const step = 0.55;

  return (
    <AbsoluteFill style={{ backgroundColor: NAVY, overflow: "hidden" }}>
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", flexDirection: "column", gap: 90 * u }}>
        <div style={{ fontFamily: FONTS.display, fontSize: 100 * u, lineHeight: 1.08, color: WHITE, textAlign: "center", maxWidth: 900 * u, opacity: show(0.05), transform: `translateY(${(1 - show(0.05)) * 26 * u}px)` }}>
          {parts.map((s, i) => <span key={i} style={{ fontWeight: s.startsWith("**") ? 800 : 300 }}>{s.replace(/\*\*/g, "")}</span>)}
        </div>
        <div style={{ display: "flex", alignItems: "flex-start", gap: 0 }}>
          {nodes.map((n, i) => {
            const k = show(0.3 + i * step * 2, 0.5, BACK);
            const arrow = show(0.3 + i * step * 2 + step, step);
            const col = NODE[i % 3];
            return (
              <React.Fragment key={i}>
                <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 26 * u, width: D }}>
                  <div style={{ width: D, height: D, borderRadius: "50%", background: col.bg, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${k})`, boxShadow: "0 22px 50px rgba(0,0,0,0.35)" }}>
                    <svg width={D * 0.55} height={D * 0.55} viewBox="0 0 100 100">
                      <path d={n.icon} fill="none" stroke={col.fg} strokeWidth={i === 1 ? 9 : 5} strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - show(0.5 + i * step * 2, 0.6)} />
                    </svg>
                  </div>
                  <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 28 * u, letterSpacing: "0.24em", textTransform: "uppercase", color: MIST, textAlign: "center", opacity: k }}>{n.label}</div>
                </div>
                {i < nodes.length - 1 ? (
                  <svg width={90 * u} height={D} viewBox="0 0 90 230" style={{ flexShrink: 0 }}>
                    <path d="M6 115 H76" fill="none" stroke={WHITE} strokeWidth={4} strokeDasharray="8 8" strokeDashoffset={-f * 0.8} style={{ clipPath: `inset(0 ${(1 - arrow) * 100}% 0 0)` }} />
                    <path d="M66 103 L80 115 L66 127" fill="none" stroke={WHITE} strokeWidth={4} strokeLinecap="round" strokeLinejoin="round" opacity={arrow > 0.95 ? 1 : 0} />
                  </svg>
                ) : null}
              </React.Fragment>
            );
          })}
        </div>
        {tag ? (
          <div style={{ border: `${3 * u}px solid ${WHITE}`, color: WHITE, borderRadius: 999, padding: `${18 * u}px ${44 * u}px`, fontFamily: FONTS.body, fontWeight: 600, fontSize: 32 * u, letterSpacing: "0.2em", textTransform: "uppercase", opacity: show(0.3 + nodes.length * step * 2), transform: `scale(${0.8 + 0.2 * show(0.3 + nodes.length * step * 2, 0.5, BACK)})` }}>{tag}</div>
        ) : null}
      </AbsoluteFill>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: RED }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default FluxoAutomatico;
